"""Helpers for shapes."""
import asyncio
import collections.abc


def flatten(obj, prefix=""):
    out = {}
    for key in sorted(obj):
        value = obj[key]
        name = prefix + str(key)
        if isinstance(value, collections.abc.Mapping):
            out.update(flatten(value, name + "."))
        else:
            out[name] = value
    return out


def is_table(x):
    return isinstance(x, collections.abc.Mapping)


async def double(x):
    await asyncio.sleep(0)
    return x * 2


async def _pipeline(values):
    out = []
    for v in values:
        out.append(await double(v))
    return out


def run_pipeline(values):
    loop = asyncio.new_event_loop()
    try:
        return loop.run_until_complete(_pipeline(values))
    finally:
        loop.close()

