"""Helpers for encoding."""
import importlib.util
import locale
import xml.etree.ElementTree as ET


def money(amount):
    locale.setlocale(locale.LC_ALL, "C")
    return locale.format_string("%.2f", amount, grouping=True)


def child_tags(xml_text):
    root = ET.fromstring(xml_text)
    return [c.tag for c in list(root)]


def item_ids(xml_text):
    root = ET.fromstring(xml_text)
    return [e.get("id") for e in root.iter("item")]


def module_exists(name):
    return importlib.util.find_spec(name) is not None


def names_found(names):
    return [n for n in names if module_exists(n)]

